WITH dim_totals AS (SELECT s.country, e.event_type, COUNT(*) AS rows_total, AVG(e.duration_sec) AS avg_duration_sec FROM web_events e LEFT JOIN sessions s ON e.session_id = s.id GROUP BY GROUPING SETS ((s.country, e.event_type), (s.country), ())) SELECT country, rows_total, avg_duration_sec, CASE WHEN country RLIKE '^(US|SG)$' THEN 'CORE' WHEN country RLIKE '^(TH|JP)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS country_zone FROM dim_totals ORDER BY country_zone DESC, rows_total DESC
